import{z as E,x as d,o as s,c as p,q as o,j as l,D as t,d as n,s as i,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"快速幂与矩阵幂","description":"","frontmatter":{"title":"快速幂与矩阵幂","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fast-exponentiation.md","filePath":"cs/fast-exponentiation.md","lastUpdated":1791413859000}'),m={name:"cs/fast-exponentiation.md"};function h(u,a,A,f,C,D){const r=d("Mermaid");return s(),p("div",null,[a[2]||(a[2]=o('<h1 id="快速幂与矩阵幂" tabindex="-1">快速幂与矩阵幂 <a class="header-anchor" href="#快速幂与矩阵幂" aria-label="Permalink to &quot;快速幂与矩阵幂&quot;">​</a></h1><div class="epigraph"><p>$a^n$ 用二进制平方：$n$ 的每一位对应一次乘；矩阵同法，线性递推第 $n$ 项因此 $\\log n$ 次矩阵乘。</p><footer>—— 据 Knuth, The Art of Computer Programming, 卷 2 半数值算法；CLRS 第 4、28 章整理</footer></div><p>上一课<a href="/cs/graph-streaming">图流</a>收束图进阶。本单元进入数值与代数。主干循环里 \\(n\\) 次乘已会。缺口是<strong>指数的对数次乘法</strong>：平方–乘。矩阵幂把常系数线性递推送到 \\(\\Theta(\\log n)\\) 次 \\(k\\times k\\) 乘。不重写主定理。后课高精度再谈大整数本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标量 \\(a^n\\)：写 \\(n=\\sum b_i 2^i\\)，维护 \\(a^{2^i}\\) 平方，遇 \\(b_i=1\\) 乘入答案。\\(O(\\log n)\\) 次乘。模 \\(m\\) 时每次模，接<a href="/cs/modular-arithmetic">模运算</a>。矩阵 \\(A^n\\) 同形，乘法换成矩阵乘 \\(O(k^\\omega)\\)。线性递推 \\(f_n=a_1 f_{n-1}+\\cdots+a_k f_{n-k}\\) 伴生矩阵 \\(k\\times k\\)，第 \\(n\\) 项在 \\(A^{n}\\) 里。</p><p>缺口是结合律下的平方，不是 FFT（后课）。<span class="marginnote">常见误区：初学者容易以为每一位的 \\(a^{2^i}\\) 都要单独重算；实际上底数每平方一次就自动得到下一位——\\(a\\to a^2\\to a^4\\to a^8\\) 一路滚上去，这正是把 \\(n\\) 次乘压缩成 \\(\\log n\\) 次的全部来源。</span></p><h3 id="不是浮点" tabindex="-1">不是浮点 \\(e^{n\\ln a}\\) <a class="header-anchor" href="#不是浮点" aria-label="Permalink to &quot;不是浮点 $e^{n\\ln a}$&quot;">​</a></h3><p>浮点指数有精度与溢出。离散、矩阵、模意义下必须平方–乘。负指数在模下用逆，<a href="/cs/euclid-extended">扩欧</a> 已给。</p><p><span class="marginnote">Knuth TAOCP 卷 2 讨论幂。矩阵形式是线性代数课标准。后课 Karatsuba/FFT 加速的是「一次乘」，本课减的是乘的次数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>递归或迭代平方。注意 \\(n=0\\)。矩阵先写对乘法。模幂勿中间溢出。</p>',11)),(s(),l(B,null,{default:t(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E6%8C%87%E6%95%B0%20n%20%E4%BA%8C%E8%BF%9B%E5%88%B6%22%5D%20--%3E%20SQ%5B%22%E5%8F%8D%E5%A4%8D%E5%B9%B3%E6%96%B9%22%5D%0A%20%20SQ%20--%3E%20MUL%5B%22%E6%AF%94%E7%89%B9%201%20%E5%88%99%E4%B9%98%E5%85%A5%22%5D%0A%20%20MUL%20--%3E%20POW%5B%22a%5En%20%E6%88%96%20A%5En%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[n("斐波那契 \\(k=2\\) 是课堂例子，不另开算法。"),e("span",{class:"marginnote"},"数字实例：把递推写成矩阵幂后，求第 \\(10^{18}\\) 个斐波那契数从「循环 \\(10^{18}\\) 次」变成「约 60 次 \\(2\\times2\\) 矩阵乘」——竞赛里能秒算天文数字的项，靠的就是这个改写。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"结合律保证 \\((A^2)^{n/2}=A^n\\)。与树上倍增同一二进制分解，对象换成半群。非结合运算不能乱平方。半环上最短路矩阵幂是 Floyd 另一叙述，本课点名不写。",-1)),(s(),l(B,null,{default:t(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E7%AE%97%20a%5E13%EF%BC%8C13%20%3D%201101%E2%82%82%22%5D%20--%3E%20S0%5B%22result%20%3D%201%EF%BC%8Cbase%20%3D%20a%22%5D%0A%20%20S0%20--%3E%20B1%5B%22%E4%BD%8D%201%EF%BC%9Aresult%C3%97a%20%3D%20a%EF%BC%9Bbase%20%E5%B9%B3%E6%96%B9%E4%B8%BA%20a%C2%B2%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E4%BD%8D%200%EF%BC%9Aresult%20%E4%BB%8D%E4%B8%BA%20a%EF%BC%9Bbase%20%E5%B9%B3%E6%96%B9%E4%B8%BA%20a%E2%81%B4%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E4%BD%8D%201%EF%BC%9Aresult%C3%97a%E2%81%B4%20%3D%20a%E2%81%B5%EF%BC%9Bbase%20%E5%B9%B3%E6%96%B9%E4%B8%BA%20a%E2%81%B8%22%5D%0A%20%20B3%20--%3E%20B4%5B%22%E4%BD%8D%201%EF%BC%9Aresult%C3%97a%E2%81%B8%20%3D%20a%C2%B9%C2%B3%EF%BC%8C%E5%AE%8C%E6%88%90%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">术语翻译：平方–乘就是按指数的二进制从低位往高位扫——每移一位把底数平方一次，扫到 1 就把当前的平方结果乘进答案。它能成立只靠一件事：乘法结合律让 \\((a^2)^{2^k}\\) 等于 \\(a^{2^{k+1}}\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写快速矩阵乘的 \\(\\omega\\) 历史（Strassen 后课）。不写离散对数（后课 BSGS）。后课默认：\\(a^n\\) 与 \\(A^n\\) 皆 \\(O(\\log n)\\) 次乘。下一课高精度算术。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>平方–乘 \\(O(\\log n)\\) 次乘。</li><li>线性递推 = 伴生矩阵幂。</li><li>模下每次取模；浮点指数不是同一问题。</li><li>出处：Knuth TAOCP 卷 2；CLRS。</li></ul>',5))])}const b=E(m,[["render",h]]);export{_ as __pageData,b as default};
